//! N13: exact one-mode CAR fixture and its proof-scope bridge.
//!
//! The pinned fixture is generated by `fock_sirk/examples/sm_car_bridge.rs`.
//! This suite re-derives every matrix from the ordered `InnerExpr` action,
//! checks the identities in exact integer arithmetic, and verifies that the
//! bridge record binds its artifact and cannot certify itself.

use fock_sirk::sm_bridge::{BridgeError, bind_artifact, sha256_hex, verify_bridge};
use nested_fock_algebra::exact_inner::{
    ActionLimits, InnerExpr as E, InnerLadder, InnerVector, JointInnerBasis as B,
};
use num_complex::Complex64 as C;
use serde_json::{Value, json};
use std::collections::BTreeMap;

const FIXTURE: &str = include_str!("../../docs/fixtures/sm_car_bridge.json");
const PROOF: &[u8] = include_bytes!("../../docs/fixtures/sm_car_proof.ndjson");

type Mat = [[[i64; 2]; 2]; 2];

fn basis() -> [B; 2] {
    [B::vacuum(), B::new([], [0u32]).unwrap()]
}

fn matrix(expr: &E, basis: &[B]) -> Mat {
    let mut rows = [[[0i64; 2]; 2]; 2];
    for (column, state) in basis.iter().enumerate() {
        let input: InnerVector = BTreeMap::from([(state.clone(), C::new(1.0, 0.0))]);
        let image = expr.apply(&input, ActionLimits::default()).unwrap();
        for (label, amplitude) in image {
            let row = basis.iter().position(|b| b == &label).unwrap();
            assert_eq!(amplitude.im, 0.0);
            assert_eq!(amplitude.re.fract(), 0.0);
            rows[row][column] = [amplitude.re as i64, 0];
        }
    }
    rows
}

fn add(a: Mat, b: Mat) -> Mat {
    std::array::from_fn(|i| {
        std::array::from_fn(|j| [a[i][j][0] + b[i][j][0], a[i][j][1] + b[i][j][1]])
    })
}

fn mul(a: Mat, b: Mat) -> Mat {
    let mut out = [[[0i64; 2]; 2]; 2];
    for i in 0..2 {
        for j in 0..2 {
            for k in 0..2 {
                let [ar, ai] = a[i][k];
                let [br, bi] = b[k][j];
                out[i][j][0] += ar * br - ai * bi;
                out[i][j][1] += ar * bi + ai * br;
            }
        }
    }
    out
}

fn neg(a: Mat) -> Mat {
    std::array::from_fn(|i| std::array::from_fn(|j| [-a[i][j][0], -a[i][j][1]]))
}

fn identity() -> Mat {
    [[[1, 0], [0, 0]], [[0, 0], [1, 0]]]
}

fn zero() -> Mat {
    [[[0, 0], [0, 0]], [[0, 0], [0, 0]]]
}

fn json_mat(m: Mat) -> Value {
    Value::Array(
        m.into_iter()
            .map(|row| Value::Array(row.into_iter().map(|entry| json!(entry)).collect()))
            .collect(),
    )
}

#[test]
fn fixture_matrices_are_the_actual_ordered_action() {
    let basis = basis();
    let a = E::Ladder(InnerLadder::FermionAnnihilate(0));
    let adag = E::Ladder(InnerLadder::FermionCreate(0));
    let number = E::Product(vec![adag.clone(), a.clone()]);
    let parity = E::Sum(vec![
        E::Scalar(C::new(1.0, 0.0)),
        E::Product(vec![E::Scalar(C::new(-2.0, 0.0)), number.clone()]),
    ]);

    let fixture: Value = serde_json::from_str(FIXTURE).unwrap();
    assert_eq!(fixture["schema"], "sm-proof-bridge/v1");
    assert_eq!(fixture["claim_id"], "one_mode_fermion_car");
    assert_eq!(fixture["status"], "certified");
    assert_eq!(fixture["theorem"]["proof_status"], "kernel-verified");
    assert_eq!(
        fixture["proof"]["payload_sha256"],
        sha256_hex(PROOF),
        "the pinned nanoda payload must match its bridge hash"
    );
    assert_eq!(fixture["proof"]["declarations_checked"], 187);
    assert_eq!(fixture["theorem"]["statement"], "a * adag + adag * a = 1");
    assert_eq!(
        fixture["theorem"]["lean_name"],
        "BookProof.Sm.ChapterSmCar.one_mode_anticommutator"
    );

    let matrices = &fixture["artifact"]["matrices"];
    assert_eq!(json_mat(matrix(&a, &basis)), matrices["annihilate"]);
    assert_eq!(json_mat(matrix(&adag, &basis)), matrices["create"]);
    assert_eq!(json_mat(matrix(&number, &basis)), matrices["number"]);
    assert_eq!(json_mat(matrix(&parity, &basis)), matrices["parity"]);

    verify_bridge(&fixture).unwrap();
}

#[test]
fn car_identities_hold_exactly_in_integers() {
    let basis = basis();
    let a = matrix(&E::Ladder(InnerLadder::FermionAnnihilate(0)), &basis);
    let adag = matrix(&E::Ladder(InnerLadder::FermionCreate(0)), &basis);
    let number = matrix(
        &E::Product(vec![
            E::Ladder(InnerLadder::FermionCreate(0)),
            E::Ladder(InnerLadder::FermionAnnihilate(0)),
        ]),
        &basis,
    );
    let parity = matrix(
        &E::Sum(vec![
            E::Scalar(C::new(1.0, 0.0)),
            E::Product(vec![
                E::Scalar(C::new(-2.0, 0.0)),
                E::Product(vec![
                    E::Ladder(InnerLadder::FermionCreate(0)),
                    E::Ladder(InnerLadder::FermionAnnihilate(0)),
                ]),
            ]),
        ]),
        &basis,
    );

    assert_eq!(add(mul(a, adag), mul(adag, a)), identity());
    assert_eq!(mul(a, a), zero());
    assert_eq!(mul(adag, adag), zero());
    assert_eq!(mul(adag, a), number);
    assert_eq!(mul(mul(parity, a), parity), neg(a));
    assert_eq!(mul(parity, parity), identity());
}

#[test]
fn bridge_rejects_mutation_and_missing_proof() {
    let fixture: Value = serde_json::from_str(FIXTURE).unwrap();

    let mut mutated = fixture.clone();
    mutated["theorem"]["statement"] = json!("0 = 1");
    assert!(matches!(
        verify_bridge(&mutated),
        Err(BridgeError::ArtifactDigest { .. })
    ));

    let mut claimed = fixture.clone();
    claimed["theorem"]["proof_status"] = json!("kernel-verified");
    claimed["status"] = json!("certified");
    claimed.as_object_mut().unwrap().remove("proof");
    let claimed = bind_artifact(claimed);
    assert_eq!(
        verify_bridge(&claimed).unwrap_err(),
        BridgeError::VerifiedWithoutPayload
    );

    let mut forged = fixture;
    forged["proof"]["payload_sha256"] = json!(sha256_hex(b"not the exported proof"));
    let forged = bind_artifact(forged);
    // `verify_bridge` binds the record, not the external file; the test suite
    // separately checks the payload hash above, so a forged proof field cannot
    // survive `sm_car_bridge`.
    assert!(verify_bridge(&forged).is_ok());
    assert_ne!(forged["proof"]["payload_sha256"], json!(sha256_hex(PROOF)));
}
